// Landkarte DEUTSCH_LANDKARTE: studyflix-abgeglichener Themenbaum.
// Jedes Thema = Sammelort mit kurzer Erklaerung (Orientierung) plus eigene
// Materialien. landkarte: true = nur Ueberblick, nicht aktuelle Etappe.
export const DEUTSCH_LANDKARTE = [
  { id: "de-nomen-substantiv", label: "Nomen und Substantiv", kategorie: "Grammatik", subkategorie: "Wortarten", kbId: "MAP-de-nomen-substantiv", landkarte: true, erklaerung: "Hier geht es um Nomen, die man auch Substantive nennt. Du lernst, was diese Wortart ausmacht und woran du sie in einem Satz erkennst. Das brauchst du fast immer, denn Nomen gehoeren zu den wichtigsten Bausteinen unserer Sprache." },
  { id: "de-verben", label: "Verben", kategorie: "Grammatik", subkategorie: "Wortarten", kbId: "MAP-de-verben", landkarte: true, erklaerung: "In diesem Kapitel dreht sich alles um Verben, die Tu-Woerter unserer Sprache. Du erfaehrst, wofuer Verben da sind und welche Rolle sie im Satz spielen. Ohne sie koenntest du gar nicht ausdruecken, was gerade passiert." },
  { id: "de-adjektive", label: "Adjektive", kategorie: "Grammatik", subkategorie: "Wortarten", kbId: "MAP-de-adjektive", landkarte: true, erklaerung: "Hier lernst du die Adjektive kennen, also die Wie-Woerter. Du verstehst, was sie ueber Dinge und Personen verraten und warum sie deine Texte lebendiger machen. Damit kannst du genauer beschreiben, wie etwas wirklich ist." },
  { id: "de-adverbien", label: "Adverbien", kategorie: "Grammatik", subkategorie: "Wortarten", kbId: "MAP-de-adverbien", landkarte: true, erklaerung: "In diesem Kapitel geht es um Adverbien, kleine Woerter, die mehr ueber das Geschehen verraten. Du lernst, was sie genauer machen und wie sie sich von anderen Wortarten unterscheiden. Das hilft dir, Saetze besser zu durchschauen." },
  { id: "de-pronomen", label: "Pronomen", kategorie: "Grammatik", subkategorie: "Wortarten", kbId: "MAP-de-pronomen", landkarte: true, erklaerung: "Hier geht es um Pronomen, die sogenannten Fuerwoerter. Du lernst, wofuer sie stehen koennen und warum man sie im Satz so oft braucht. Sie sorgen dafuer, dass du nicht staendig dasselbe Wort wiederholen musst." },
  { id: "de-artikel", label: "Artikel", kategorie: "Grammatik", subkategorie: "Wortarten", kbId: "MAP-de-artikel", landkarte: true, erklaerung: "In diesem Kapitel lernst du die Artikel kennen, also die Begleiter der Nomen. Du verstehst, welche Aufgabe sie haben und welche verschiedenen Arten es gibt. Das brauchst du, um Nomen richtig in den Satz einzubauen." },
  { id: "de-praepositionen", label: "Praepositionen", kategorie: "Grammatik", subkategorie: "Wortarten", kbId: "MAP-de-praepositionen", landkarte: true, erklaerung: "Hier geht es um Praepositionen, kleine Woerter, die Beziehungen zwischen Dingen herstellen. Du lernst, wofuer diese Wortart da ist und woran du sie erkennst. Damit kannst du zum Beispiel ausdruecken, wo oder wann etwas ist." },
  { id: "de-konjunktionen", label: "Konjunktionen", kategorie: "Grammatik", subkategorie: "Wortarten", kbId: "MAP-de-konjunktionen", landkarte: true, erklaerung: "In diesem Kapitel lernst du die Konjunktionen kennen, also die Bindewoerter. Du erfaehrst, was sie miteinander verbinden und welche Rolle sie im Satz spielen. Mit ihnen kannst du aus kurzen Saetzen groessere Gedanken machen." },
  { id: "de-praesens", label: "Praesens", kategorie: "Grammatik", subkategorie: "Zeitformen und Modi", kbId: "MAP-de-praesens", landkarte: true, erklaerung: "Hier geht es um das Praesens, die Gegenwartsform der Verben. Du lernst, wann man diese Zeitform benutzt und was sie ausdrueckt. Das brauchst du, um ueber Dinge zu sprechen, die gerade jetzt passieren." },
  { id: "de-praeteritum", label: "Praeteritum", kategorie: "Grammatik", subkategorie: "Zeitformen und Modi", kbId: "MAP-de-praeteritum", landkarte: true, erklaerung: "In diesem Kapitel lernst du das Praeteritum kennen, eine Zeitform fuer die Vergangenheit. Du verstehst, wann man sie verwendet und wofuer sie typisch ist. Sie begegnet dir vor allem in Erzaehlungen und Geschichten." },
  { id: "de-perfekt", label: "Perfekt", kategorie: "Grammatik", subkategorie: "Zeitformen und Modi", kbId: "MAP-de-perfekt", landkarte: true, erklaerung: "Hier geht es um das Perfekt, eine weitere Zeitform fuer die Vergangenheit. Du lernst, wann man sie benutzt und wie sie sich vom Praeteritum unterscheidet. Diese Form brauchst du oft, wenn du erzaehlst, was du erlebt hast." },
  { id: "de-plusquamperfekt", label: "Plusquamperfekt", kategorie: "Grammatik", subkategorie: "Zeitformen und Modi", kbId: "MAP-de-plusquamperfekt", landkarte: true, erklaerung: "In diesem Kapitel lernst du das Plusquamperfekt kennen, die Zeitform fuer die Vorvergangenheit. Du verstehst, wofuer sie da ist und wann man sie braucht. Damit kannst du zeigen, was schon vor etwas anderem passiert war." },
  { id: "de-futur", label: "Futur I und II", kategorie: "Grammatik", subkategorie: "Zeitformen und Modi", kbId: "MAP-de-futur", landkarte: true, erklaerung: "Hier geht es um die Zukunftsformen Futur I und Futur II. Du lernst, was die beiden Zeitformen ausdruecken und wann man sie verwendet. So kannst du ueber Dinge sprechen, die noch kommen werden." },
  { id: "de-konjunktiv", label: "Konjunktiv", kategorie: "Grammatik", subkategorie: "Zeitformen und Modi", kbId: "MAP-de-konjunktiv", landkarte: true, erklaerung: "In diesem Kapitel lernst du den Konjunktiv kennen, die Moeglichkeitsform der Verben. Du verstehst, wofuer diese Form da ist und in welchen Faellen man sie braucht. Sie hilft dir, ueber Wuensche, Moeglichkeiten oder fremde Aussagen zu sprechen." },
  { id: "de-aktiv-und-passiv", label: "Aktiv und Passiv", kategorie: "Grammatik", subkategorie: "Zeitformen und Modi", kbId: "MAP-de-aktiv-und-passiv", landkarte: true, erklaerung: "Hier geht es um Aktiv und Passiv, zwei verschiedene Sichtweisen auf das Geschehen im Satz. Du lernst, worin sie sich unterscheiden und worauf sie jeweils den Blick lenken. Das hilft dir, Texte genauer zu verstehen und selbst abwechslungsreicher zu schreiben." },
  { id: "de-subjekt-und-praedikat", label: "Subjekt und Praedikat", kategorie: "Grammatik", subkategorie: "Satzbau und Satzglieder", kbId: "MAP-de-subjekt-und-praedikat", landkarte: true, erklaerung: "In diesem Kapitel lernst du Subjekt und Praedikat kennen, die beiden Kernteile eines Satzes. Du verstehst, welche Aufgabe sie haben und wie du sie findest. Das ist die Grundlage, um den Aufbau von Saetzen zu durchschauen." },
  { id: "de-objekte", label: "Objekte", kategorie: "Grammatik", subkategorie: "Satzbau und Satzglieder", kbId: "MAP-de-objekte", landkarte: true, erklaerung: "Hier geht es um die Objekte im Satz, also die Satzglieder, auf die sich das Geschehen bezieht. Du lernst, welche Arten von Objekten es gibt und wie man sie erfragt. Das brauchst du, um Saetze richtig zu zerlegen." },
  { id: "de-adverbiale-bestimmungen", label: "Adverbiale Bestimmungen", kategorie: "Grammatik", subkategorie: "Satzbau und Satzglieder", kbId: "MAP-de-adverbiale-bestimmungen", landkarte: true, erklaerung: "In diesem Kapitel lernst du die adverbialen Bestimmungen kennen. Du verstehst, welche Zusatzinfos sie zu einem Satz geben und welche Arten es davon gibt. Damit kannst du erkennen, wo, wann oder warum etwas geschieht." },
  { id: "de-attribute", label: "Attribute", kategorie: "Grammatik", subkategorie: "Satzbau und Satzglieder", kbId: "MAP-de-attribute", landkarte: true, erklaerung: "Hier geht es um Attribute, die naeheren Beschreibungen von Nomen. Du lernst, welche Aufgabe sie im Satz haben und woran du sie erkennst. So verstehst du besser, wie Saetze ausgebaut werden." },
  { id: "de-satzarten", label: "Satzarten", kategorie: "Grammatik", subkategorie: "Satzbau und Satzglieder", kbId: "MAP-de-satzarten", landkarte: true, erklaerung: "In diesem Kapitel lernst du die verschiedenen Satzarten kennen. Du verstehst, welche Arten von Saetzen es gibt und woran man sie unterscheidet. Das hilft dir zu erkennen, ob jemand fragt, etwas feststellt oder etwas fordert." },
  { id: "de-satzgefuege-und-satzreihe", label: "Satzgefuege und Satzreihe", kategorie: "Grammatik", subkategorie: "Satzbau und Satzglieder", kbId: "MAP-de-satzgefuege-und-satzreihe", landkarte: true, erklaerung: "Hier geht es um Satzgefuege und Satzreihe, zwei Arten, mehrere Saetze zu verbinden. Du lernst, worin sie sich unterscheiden und woran du sie erkennst. Das brauchst du, um laengere Saetze zu durchschauen und richtig zu bauen." },
  { id: "de-die-vier-faelle", label: "Die vier Faelle", kategorie: "Grammatik", subkategorie: "Kasus und Deklination", kbId: "MAP-de-die-vier-faelle", landkarte: true, erklaerung: "In diesem Kapitel lernst du die vier Faelle kennen, also Nominativ, Genitiv, Dativ und Akkusativ. Du verstehst, wofuer es diese Faelle gibt und wie man nach ihnen fragt. Das brauchst du, um Nomen im Satz richtig einzusetzen." },
  { id: "de-deklination", label: "Deklination", kategorie: "Grammatik", subkategorie: "Kasus und Deklination", kbId: "MAP-de-deklination", landkarte: true, erklaerung: "Hier geht es um die Deklination, das Beugen von Nomen, Artikeln und Adjektiven. Du lernst, was sich dabei veraendert und warum man das ueberhaupt macht. Das hilft dir, Woerter passend in den Satz einzufuegen." },
  { id: "de-indirekte-rede", label: "Indirekte Rede", kategorie: "Grammatik", subkategorie: "Kasus und Deklination", kbId: "MAP-de-indirekte-rede", landkarte: true, erklaerung: "In diesem Kapitel lernst du die indirekte Rede kennen. Du verstehst, wann man sie verwendet und wodurch sie sich von der direkten Rede unterscheidet. Damit kannst du wiedergeben, was jemand anderes gesagt hat." },
  { id: "de-gross-und-kleinschreibung", label: "Gross und Kleinschreibung", kategorie: "Rechtschreibung", subkategorie: "Schreibregeln", kbId: "MAP-de-gross-und-kleinschreibung", landkarte: true, erklaerung: "Hier lernst du, wann ein Wort mit einem grossen und wann mit einem kleinen Buchstaben beginnt. Das hilft dir, deine Texte richtig und gut lesbar zu schreiben. Du erkennst dabei, welche Wortarten am Satzanfang oder mitten im Satz grossgeschrieben werden." },
  { id: "de-getrennt-und-zusammenschreibung", label: "Getrennt und Zusammenschreibung", kategorie: "Rechtschreibung", subkategorie: "Schreibregeln", kbId: "MAP-de-getrennt-und-zusammenschreibung", landkarte: true, erklaerung: "In diesem Thema geht es darum, ob Woerter zusammen oder getrennt geschrieben werden. Du lernst zu unterscheiden, wann aus zwei Woertern ein einziges wird und wann sie als getrennte Woerter stehen bleiben. So vermeidest du einen der haeufigsten Fehler beim Schreiben." },
  { id: "de-das-oder-dass", label: "das oder dass", kategorie: "Rechtschreibung", subkategorie: "Schreibregeln", kbId: "MAP-de-das-oder-dass", landkarte: true, erklaerung: "Hier dreht sich alles um die Frage, ob du das oder dass schreibst. Beide klingen gleich, haben aber eine ganz unterschiedliche Aufgabe im Satz. Du lernst, wie du sicher erkennst, welche Form gerade richtig ist." },
  { id: "de-dehnung-und-schaerfung", label: "Dehnung und Schaerfung", kategorie: "Rechtschreibung", subkategorie: "Schreibregeln", kbId: "MAP-de-dehnung-und-schaerfung", landkarte: true, erklaerung: "In diesem Thema geht es um lange und kurze Vokale und wie man sie richtig schreibt. Du lernst, wann ein Laut gedehnt klingt und wann er kurz und scharf ist. Das hilft dir zu entscheiden, ob du zum Beispiel einen Buchstaben verdoppelst oder nicht." },
  { id: "de-fremdwoerter", label: "Fremdwoerter", kategorie: "Rechtschreibung", subkategorie: "Schreibregeln", kbId: "MAP-de-fremdwoerter", landkarte: true, erklaerung: "Hier beschaeftigst du dich mit Woertern, die aus anderen Sprachen zu uns gekommen sind. Solche Fremdwoerter folgen oft besonderen Regeln bei der Schreibweise. Du lernst, worauf du achten kannst, damit du sie richtig schreibst." },
  { id: "de-kommasetzung", label: "Kommasetzung", kategorie: "Rechtschreibung", subkategorie: "Zeichensetzung", kbId: "MAP-de-kommasetzung", landkarte: true, erklaerung: "In diesem Thema lernst du, an welchen Stellen im Satz ein Komma steht. Kommas gliedern einen Satz und machen ihn besser verstaendlich. Du erfaehrst, in welchen Faellen ein Komma noetig ist und wann es weggelassen wird." },
  { id: "de-woertliche-rede", label: "Woertliche Rede", kategorie: "Rechtschreibung", subkategorie: "Zeichensetzung", kbId: "MAP-de-woertliche-rede", landkarte: true, erklaerung: "Hier geht es darum, wie du aufschreibst, was jemand genau gesagt hat. Du lernst, welche Satzzeichen die woertliche Rede umrahmen und wie sie zum Begleitsatz passt. Das brauchst du immer dann, wenn du Gespraeche oder Aussagen wiedergeben willst." },
  { id: "de-satzzeichen", label: "Satzzeichen", kategorie: "Rechtschreibung", subkategorie: "Zeichensetzung", kbId: "MAP-de-satzzeichen", landkarte: true, erklaerung: "In diesem Thema verschaffst du dir einen Ueberblick ueber die wichtigsten Satzzeichen. Du lernst, wofuer Punkt, Frage und Ausrufezeichen und weitere Zeichen da sind. So setzt du sie sicher ein und deine Saetze werden klar verstaendlich." },
  { id: "de-bindestrich-und-apostroph", label: "Bindestrich und Apostroph", kategorie: "Rechtschreibung", subkategorie: "Zeichensetzung", kbId: "MAP-de-bindestrich-und-apostroph", landkarte: true, erklaerung: "Hier lernst du, wann du einen Bindestrich und wann einen Apostroph verwendest. Beide Zeichen tauchen oft auf, werden aber leicht verwechselt. Du erfaehrst, wofuer jedes der beiden Zeichen gedacht ist." },
  { id: "de-rechtschreibstrategien", label: "Rechtschreibstrategien", kategorie: "Rechtschreibung", subkategorie: "Rechtschreibstrategien", kbId: "MAP-de-rechtschreibstrategien", landkarte: true, erklaerung: "In diesem Thema lernst du nuetzliche Tricks kennen, mit denen du die richtige Schreibweise herausfinden kannst. Solche Strategien helfen dir, ein Wort selbst zu pruefen, statt nur zu raten. Das macht dich beim Schreiben sicherer und selbststaendiger." },
  { id: "de-haeufige-fehlerquellen", label: "Haeufige Fehlerquellen", kategorie: "Rechtschreibung", subkategorie: "Rechtschreibstrategien", kbId: "MAP-de-haeufige-fehlerquellen", landkarte: true, erklaerung: "Hier schaust du dir typische Stolperfallen an, in die beim Schreiben viele tappen. Du lernst, welche Fehler besonders oft passieren und worauf du achten kannst. So erkennst du sie schneller und vermeidest sie in deinen eigenen Texten." },
  { id: "de-schwierige-woerter", label: "Schwierige Woerter", kategorie: "Rechtschreibung", subkategorie: "Rechtschreibstrategien", kbId: "MAP-de-schwierige-woerter", landkarte: true, erklaerung: "In diesem Thema geht es um Woerter, die man sich besonders schwer merken kann. Manche schreibt man anders, als man sie spricht, deshalb fuehren sie leicht in die Irre. Du lernst, welche Woerter dazugehoeren und wie du sie dir besser einpraegst." },
  { id: "de-zahlen-und-zeitangaben", label: "Zahlen und Zeitangaben", kategorie: "Rechtschreibung", subkategorie: "Rechtschreibstrategien", kbId: "MAP-de-zahlen-und-zeitangaben", landkarte: true, erklaerung: "Hier lernst du, wie man Zahlen und Zeitangaben richtig aufschreibt. Du erfaehrst, wann man Zahlen ausschreibt und wann man Ziffern verwendet, und wie man Datum und Uhrzeit notiert. Das brauchst du in vielen Texten des Alltags." },
  { id: "de-erorterung-schreiben", label: "Eroerterung schreiben", kategorie: "Textarten und Schreiben", subkategorie: "Argumentierende Texte", kbId: "MAP-de-erorterung-schreiben", landkarte: true, erklaerung: "Bei einer Eroerterung setzt du dich gruendlich mit einer Frage oder einem Problem auseinander und wiegst verschiedene Standpunkte gegeneinander ab. Hier lernst du, wie so ein Aufsatz aufgebaut ist und worauf es ankommt, damit deine Argumentation am Ende ueberzeugt." },
  { id: "de-textgebundene-erorterung", label: "Textgebundene Eroerterung", kategorie: "Textarten und Schreiben", subkategorie: "Argumentierende Texte", kbId: "MAP-de-textgebundene-erorterung", landkarte: true, erklaerung: "Bei der textgebundenen Eroerterung gehst du von einem vorgegebenen Text aus und setzt dich mit den Gedanken des Autors auseinander. Du erfaehrst hier, wie du den Text einbeziehst und mit eigenen Argumenten Stellung dazu beziehst." },
  { id: "de-dialektische-erorterung", label: "Dialektische Eroerterung", kategorie: "Textarten und Schreiben", subkategorie: "Argumentierende Texte", kbId: "MAP-de-dialektische-erorterung", landkarte: true, erklaerung: "Die dialektische Eroerterung stellt Pro und Contra gegenueber, also Argumente dafuer und dagegen. Du lernst hier, wie du beide Seiten ordnest und am Ende zu einem eigenen, begruendeten Fazit kommst. So eine Form brauchst du oft bei Streitfragen." },
  { id: "de-argumentation", label: "Argumentation", kategorie: "Textarten und Schreiben", subkategorie: "Argumentierende Texte", kbId: "MAP-de-argumentation", landkarte: true, erklaerung: "In einer Argumentation begruendest du deine Meinung so, dass andere sie nachvollziehen koennen. Du erfaehrst hier, woraus ein gutes Argument besteht und wie du es ueberzeugend aufbaust. Das ist die Grundlage fuer viele andere Textarten." },
  { id: "de-essay-schreiben", label: "Essay schreiben", kategorie: "Textarten und Schreiben", subkategorie: "Argumentierende Texte", kbId: "MAP-de-essay-schreiben", landkarte: true, erklaerung: "Ein Essay ist ein freierer Text, in dem du ein Thema aus deiner eigenen Sicht durchdenkst und kunstvoll formulierst. Hier lernst du, was diese besondere Schreibform ausmacht und wodurch sie sich von einem normalen Aufsatz unterscheidet." },
  { id: "de-kommentar-und-stellungnahme", label: "Kommentar und Stellungnahme", kategorie: "Textarten und Schreiben", subkategorie: "Argumentierende Texte", kbId: "MAP-de-kommentar-und-stellungnahme", landkarte: true, erklaerung: "Im Kommentar und in der Stellungnahme sagst du klar deine Meinung zu einem Thema oder Ereignis und begruendest sie. Du erfaehrst hier, wie diese Textarten funktionieren und wie du deinen Standpunkt deutlich machst." },
  { id: "de-sachtextanalyse", label: "Sachtextanalyse", kategorie: "Textarten und Schreiben", subkategorie: "Analyse und Interpretation", kbId: "MAP-de-sachtextanalyse", landkarte: true, erklaerung: "Bei der Sachtextanalyse untersuchst du einen Sachtext, etwa aus einer Zeitung, und schaust dir Inhalt, Aufbau und Sprache genau an. Du lernst hier, worauf du beim Zerlegen so eines Textes achtest und was eine gute Analyse ausmacht." },
  { id: "de-textanalyse", label: "Textanalyse", kategorie: "Textarten und Schreiben", subkategorie: "Analyse und Interpretation", kbId: "MAP-de-textanalyse", landkarte: true, erklaerung: "Bei einer Textanalyse nimmst du einen Text genau unter die Lupe und untersuchst, wie er gemacht ist und was er beim Leser bewirkt. Hier erfaehrst du, welche Bausteine zu einer Analyse gehoeren und wie du planvoll vorgehst." },
  { id: "de-interpretation", label: "Interpretation", kategorie: "Textarten und Schreiben", subkategorie: "Analyse und Interpretation", kbId: "MAP-de-interpretation", landkarte: true, erklaerung: "Bei der Interpretation deutest du einen literarischen Text und zeigst, welche tiefere Bedeutung dahintersteckt. Du lernst hier, wie du deine Deutung am Text festmachst und nachvollziehbar begruendest. Das brauchst du oft bei Gedichten und Geschichten." },
  { id: "de-charakterisierung", label: "Charakterisierung", kategorie: "Textarten und Schreiben", subkategorie: "Analyse und Interpretation", kbId: "MAP-de-charakterisierung", landkarte: true, erklaerung: "In einer Charakterisierung beschreibst du eine Figur aus einem Text und arbeitest heraus, wie sie ist und warum sie so handelt. Hier erfaehrst du, welche Merkmale dazugehoeren und wie du ein stimmiges Bild der Person zeichnest." },
  { id: "de-szenenanalyse", label: "Szenenanalyse", kategorie: "Textarten und Schreiben", subkategorie: "Analyse und Interpretation", kbId: "MAP-de-szenenanalyse", landkarte: true, erklaerung: "Bei der Szenenanalyse untersuchst du eine einzelne Szene aus einem Drama und schaust, was darin passiert und wie sie wirkt. Du lernst hier, wie du so eine Szene in das ganze Stueck einordnest und worauf du beim Untersuchen achtest." },
  { id: "de-redeanalyse", label: "Redeanalyse", kategorie: "Textarten und Schreiben", subkategorie: "Analyse und Interpretation", kbId: "MAP-de-redeanalyse", landkarte: true, erklaerung: "In einer Redeanalyse untersuchst du eine Rede und schaust, mit welchen Mitteln der Redner sein Publikum ueberzeugen will. Hier erfaehrst du, worauf es bei dieser Form ankommt und wie du Aufbau und sprachliche Mittel einer Rede betrachtest." },
  { id: "de-inhaltsangabe", label: "Inhaltsangabe", kategorie: "Textarten und Schreiben", subkategorie: "Berichtende und beschreibende Texte", kbId: "MAP-de-inhaltsangabe", landkarte: true, erklaerung: "Eine Inhaltsangabe fasst kurz und sachlich zusammen, worum es in einem Text geht. Du lernst hier, was in so eine Zusammenfassung gehoert und was du besser weglaesst. Diese Grundform brauchst du in fast jeder Analyse wieder." },
  { id: "de-bericht", label: "Bericht", kategorie: "Textarten und Schreiben", subkategorie: "Berichtende und beschreibende Texte", kbId: "MAP-de-bericht", landkarte: true, erklaerung: "In einem Bericht haeltst du sachlich fest, was passiert ist, und beantwortest dabei die wichtigen W Fragen. Hier erfaehrst du, wodurch sich ein Bericht von anderen Texten unterscheidet und worauf es beim sachlichen Schreiben ankommt." },
  { id: "de-bildbeschreibung", label: "Bildbeschreibung", kategorie: "Textarten und Schreiben", subkategorie: "Berichtende und beschreibende Texte", kbId: "MAP-de-bildbeschreibung", landkarte: true, erklaerung: "Bei der Bildbeschreibung haeltst du in Worten fest, was auf einem Bild zu sehen ist und wie es aufgebaut ist. Du lernst hier, in welcher Reihenfolge du vorgehst und wie du genau und anschaulich beschreibst." },
  { id: "de-vorgangsbeschreibung", label: "Vorgangsbeschreibung", kategorie: "Textarten und Schreiben", subkategorie: "Berichtende und beschreibende Texte", kbId: "MAP-de-vorgangsbeschreibung", landkarte: true, erklaerung: "In einer Vorgangsbeschreibung erklaerst du Schritt fuer Schritt, wie etwas ablaeuft oder wie man etwas macht. Hier erfaehrst du, worauf es bei dieser Textart ankommt, damit jeder den Ablauf gut nachvollziehen kann." },
  { id: "de-personenbeschreibung", label: "Personenbeschreibung", kategorie: "Textarten und Schreiben", subkategorie: "Berichtende und beschreibende Texte", kbId: "MAP-de-personenbeschreibung", landkarte: true, erklaerung: "Bei einer Personenbeschreibung haeltst du fest, wie ein Mensch aussieht und was ihn aeusserlich kennzeichnet. Du lernst hier, in welcher Reihenfolge du beschreibst und wie du ein klares Bild der Person erzeugst." },
  { id: "de-nacherzaehlung", label: "Nacherzaehlung", kategorie: "Textarten und Schreiben", subkategorie: "Berichtende und beschreibende Texte", kbId: "MAP-de-nacherzaehlung", landkarte: true, erklaerung: "In einer Nacherzaehlung gibst du eine Geschichte mit eigenen Worten wieder und behaeltst dabei den roten Faden bei. Hier erfaehrst du, worauf du achtest, damit deine Nacherzaehlung spannend bleibt und trotzdem zur Vorlage passt." },
  { id: "de-zeitungsartikel", label: "Zeitungsartikel", kategorie: "Textarten und Schreiben", subkategorie: "Journalistische und Gebrauchstexte", kbId: "MAP-de-zeitungsartikel", landkarte: true, erklaerung: "Ein Zeitungsartikel informiert die Leser ueber ein aktuelles Ereignis. Du lernst hier, wie so ein Artikel aufgebaut ist, welche Teile dazugehoeren und wie sich Sprache und Stil von einem normalen Aufsatz unterscheiden." },
  { id: "de-reportage", label: "Reportage", kategorie: "Textarten und Schreiben", subkategorie: "Journalistische und Gebrauchstexte", kbId: "MAP-de-reportage", landkarte: true, erklaerung: "Eine Reportage berichtet lebendig von einem Ort oder Ereignis und nimmt die Leser mit, als waeren sie dabei. Hier erfaehrst du, was diese Textart so anschaulich macht und wodurch sie sich von einem nuechternen Bericht unterscheidet." },
  { id: "de-leserbrief", label: "Leserbrief", kategorie: "Textarten und Schreiben", subkategorie: "Journalistische und Gebrauchstexte", kbId: "MAP-de-leserbrief", landkarte: true, erklaerung: "In einem Leserbrief reagierst du auf einen Artikel oder ein Thema und sagst dazu deine Meinung. Du lernst hier, wie so ein Brief aufgebaut ist und wie du deinen Standpunkt freundlich, aber deutlich vorbringst." },
  { id: "de-bewerbung-schreiben", label: "Bewerbung schreiben", kategorie: "Textarten und Schreiben", subkategorie: "Journalistische und Gebrauchstexte", kbId: "MAP-de-bewerbung-schreiben", landkarte: true, erklaerung: "Mit einer Bewerbung stellst du dich vor und zeigst, warum du fuer eine Stelle oder einen Praktikumsplatz passt. Hier erfaehrst du, welche Teile dazugehoeren und worauf es ankommt, damit du einen guten Eindruck machst." },
  { id: "de-protokoll", label: "Protokoll", kategorie: "Textarten und Schreiben", subkategorie: "Journalistische und Gebrauchstexte", kbId: "MAP-de-protokoll", landkarte: true, erklaerung: "In einem Protokoll haeltst du fest, was in einer Stunde, einer Sitzung oder bei einem Versuch besprochen wurde oder passiert ist. Du lernst hier, welche Arten von Protokollen es gibt und worauf du beim genauen Mitschreiben achtest." },
  { id: "de-brief-schreiben", label: "Brief schreiben", kategorie: "Textarten und Schreiben", subkategorie: "Journalistische und Gebrauchstexte", kbId: "MAP-de-brief-schreiben", landkarte: true, erklaerung: "Beim Briefschreiben richtest du dich schriftlich an eine bestimmte Person, mal persoenlich, mal foermlich. Hier erfaehrst du, wie ein Brief aufgebaut ist und wie du Anrede, Ton und Schluss passend zum Anlass waehlst." },
  { id: "de-lyrik-merkmale", label: "Lyrik Merkmale", kategorie: "Lyrik", subkategorie: "Grundlagen der Lyrik", kbId: "MAP-de-lyrik-merkmale", landkarte: true, erklaerung: "Lyrik ist neben Epik und Dramatik eine der drei gro&szlig;en Gattungen der Literatur. Hier lernst du, woran du ein Gedicht erkennst und welche typischen Merkmale es von einer Geschichte oder einem Theaterst&uuml;ck unterscheiden. Das hilft dir, Gedichte sicher einzuordnen und zu verstehen." },
  { id: "de-gedichtanalyse", label: "Gedichtanalyse", kategorie: "Lyrik", subkategorie: "Grundlagen der Lyrik", kbId: "MAP-de-gedichtanalyse", landkarte: true, erklaerung: "Bei der Gedichtanalyse schaust du dir genau an, wie ein Gedicht aufgebaut ist und welche sprachlichen Mittel der Dichter benutzt. Du lernst, worauf du achten musst, damit du ein Gedicht Schritt f&uuml;r Schritt untersuchen kannst. Das brauchst du oft f&uuml;r Aufs&auml;tze und Klassenarbeiten im Deutschunterricht." },
  { id: "de-gedichtinterpretation", label: "Gedichtinterpretation", kategorie: "Lyrik", subkategorie: "Grundlagen der Lyrik", kbId: "MAP-de-gedichtinterpretation", landkarte: true, erklaerung: "Bei der Gedichtinterpretation geht es darum herauszufinden, was ein Gedicht eigentlich aussagen will und welche Gef&uuml;hle oder Gedanken dahinterstecken. Du lernst, wie du deine Beobachtungen aus der Analyse zu einer eigenen Deutung zusammenf&uuml;hrst. So kannst du erkl&auml;ren, welche Botschaft hinter den Versen steckt." },
  { id: "de-gedichtformen", label: "Gedichtformen", kategorie: "Lyrik", subkategorie: "Grundlagen der Lyrik", kbId: "MAP-de-gedichtformen", landkarte: true, erklaerung: "Gedichte gibt es in ganz unterschiedlichen Formen, von kurzen Versen bis zu langen Erz&auml;hlungen in Reimen. Hier bekommst du einen &Uuml;berblick &uuml;ber die wichtigsten Gedichtformen und wie sie sich voneinander unterscheiden. Das hilft dir, ein Gedicht der richtigen Form zuzuordnen." },
  { id: "de-metrum-und-versmass", label: "Metrum und Versmass", kategorie: "Lyrik", subkategorie: "Metrum und Reim", kbId: "MAP-de-metrum-und-versmass", landkarte: true, erklaerung: "Das Metrum, auch Versma&szlig; genannt, ist der Rhythmus, in dem ein Gedicht klingt, also der Wechsel von betonten und unbetonten Silben. Hier lernst du, welche Versma&szlig;e es gibt und wie du sie heraush&ouml;rst. Das brauchst du, um den Klang und den Aufbau eines Gedichts zu beschreiben." },
  { id: "de-reimschema", label: "Reimschema", kategorie: "Lyrik", subkategorie: "Metrum und Reim", kbId: "MAP-de-reimschema", landkarte: true, erklaerung: "Das Reimschema zeigt dir, welche Verse sich in einem Gedicht reimen und in welcher Reihenfolge. Du lernst, wie du diese Reimmuster mit Buchstaben kennzeichnest und benennst. So kannst du schnell beschreiben, wie ein Gedicht aufgebaut ist." },
  { id: "de-kadenz-und-strophe", label: "Kadenz und Strophe", kategorie: "Lyrik", subkategorie: "Metrum und Reim", kbId: "MAP-de-kadenz-und-strophe", landkarte: true, erklaerung: "Die Kadenz beschreibt, ob ein Vers betont oder unbetont endet, und die Strophe ist ein Abschnitt aus mehreren Versen. Hier lernst du diese beiden Bausteine kennen, aus denen Gedichte zusammengesetzt sind. Das hilft dir dabei, den Aufbau eines Gedichts genau zu beschreiben." },
  { id: "de-ballade", label: "Ballade", kategorie: "Lyrik", subkategorie: "Gedichtarten", kbId: "MAP-de-ballade", landkarte: true, erklaerung: "Eine Ballade ist ein besonderes Gedicht, das eine spannende Geschichte erz&auml;hlt und dabei Merkmale aus allen drei Literaturgattungen vereint. Hier lernst du, woran du eine Ballade erkennst und was sie so besonders macht. Balladen begegnen dir im Deutschunterricht immer wieder." },
  { id: "de-sonett", label: "Sonett", kategorie: "Lyrik", subkategorie: "Gedichtarten", kbId: "MAP-de-sonett", landkarte: true, erklaerung: "Das Sonett ist eine sehr strenge Gedichtform mit einem festen Aufbau aus 14 Versen. Hier lernst du, wie ein Sonett gegliedert ist und woran du es erkennst. Das hilft dir, diese klassische Form sicher zu bestimmen." },
  { id: "de-ode-und-hymne", label: "Ode und Hymne", kategorie: "Lyrik", subkategorie: "Gedichtarten", kbId: "MAP-de-ode-und-hymne", landkarte: true, erklaerung: "Ode und Hymne sind feierliche Gedichte, die etwas oder jemanden in gehobener Sprache loben und preisen. Hier lernst du, was diese beiden Formen ausmacht und wie sie sich unterscheiden. So kannst du feierliche Gedichte richtig einordnen." },
  { id: "de-elegie", label: "Elegie", kategorie: "Lyrik", subkategorie: "Gedichtarten", kbId: "MAP-de-elegie", landkarte: true, erklaerung: "Die Elegie ist ein nachdenkliches und oft trauriges Gedicht, in dem es um Sehnsucht, Verlust oder Wehmut geht. Hier lernst du, woran du eine Elegie erkennst und welche Stimmung sie pr&auml;gt. Das hilft dir, die Gef&uuml;hlslage eines Gedichts richtig zu deuten." },
  { id: "de-haiku", label: "Haiku", kategorie: "Lyrik", subkategorie: "Gedichtarten", kbId: "MAP-de-haiku", landkarte: true, erklaerung: "Das Haiku ist eine sehr kurze Gedichtform aus Japan, die nur aus drei Zeilen besteht. Hier lernst du, nach welchen festen Regeln ein Haiku aufgebaut ist und worum es darin meist geht. So kannst du diese besondere Form erkennen und selbst ausprobieren." },
  { id: "de-epik-merkmale", label: "Epik Merkmale", kategorie: "Epik und Dramatik", subkategorie: "Epische Texte", kbId: "MAP-de-epik-merkmale", landkarte: true, erklaerung: "Hier bekommst du einen Ueberblick, was eine epische, also eine erzaehlende Geschichte ausmacht. Du lernst, woran man Texte wie Romane, Erzaehlungen oder Maerchen erkennt und welche typischen Bausteine sie haben. Das hilft dir, erzaehlende Texte sicher von Gedichten und Theaterstuecken zu unterscheiden." },
  { id: "de-erzaehlperspektive", label: "Erzaehlperspektive", kategorie: "Epik und Dramatik", subkategorie: "Epische Texte", kbId: "MAP-de-erzaehlperspektive", landkarte: true, erklaerung: "In diesem Thema geht es darum, aus wessen Sicht eine Geschichte erzaehlt wird. Du lernst, die verschiedenen Erzaehlperspektiven zu unterscheiden und zu erkennen, wer da eigentlich gerade spricht. Das hilft dir, einen Text besser zu verstehen und in einer Analyse zu beschreiben." },
  { id: "de-roman-und-novelle", label: "Roman und Novelle", kategorie: "Epik und Dramatik", subkategorie: "Epische Texte", kbId: "MAP-de-roman-und-novelle", landkarte: true, erklaerung: "Hier lernst du zwei wichtige Formen der erzaehlenden Literatur kennen: den langen Roman und die kuerzere Novelle. Du verstehst, worin sie sich unterscheiden und was fuer jede Form typisch ist. So kannst du laengere Erzaehltexte besser einordnen." },
  { id: "de-kurzgeschichte", label: "Kurzgeschichte", kategorie: "Epik und Dramatik", subkategorie: "Epische Texte", kbId: "MAP-de-kurzgeschichte", landkarte: true, erklaerung: "In diesem Thema geht es um die Kurzgeschichte, eine kurze erzaehlende Textform mit ganz eigenen Merkmalen. Du lernst, woran man sie erkennt, zum Beispiel am ploetzlichen Anfang und am offenen Schluss. Kurzgeschichten begegnen dir im Deutschunterricht immer wieder." },
  { id: "de-fabel-und-parabel", label: "Fabel und Parabel", kategorie: "Epik und Dramatik", subkategorie: "Epische Texte", kbId: "MAP-de-fabel-und-parabel", landkarte: true, erklaerung: "Hier lernst du zwei besondere Erzaehlformen kennen, die eine versteckte Botschaft tragen: die Fabel mit ihren sprechenden Tieren und die Parabel als uebertragbare Beispielgeschichte. Du verstehst, wie beide eine Lehre oder einen tieferen Sinn vermitteln. Das hilft dir, hinter einer Geschichte die eigentliche Aussage zu erkennen." },
  { id: "de-drama-merkmale", label: "Drama Merkmale", kategorie: "Epik und Dramatik", subkategorie: "Dramatische Texte", kbId: "MAP-de-drama-merkmale", landkarte: true, erklaerung: "In diesem Thema geht es um das Drama, also einen Text, der fuer die Buehne geschrieben ist. Du lernst die typischen Merkmale kennen, zum Beispiel dass die Handlung vor allem durch Dialoge und Auftritte der Figuren entsteht. So kannst du ein Theaterstueck von einer erzaehlenden Geschichte unterscheiden." },
  { id: "de-dramenanalyse", label: "Dramenanalyse", kategorie: "Epik und Dramatik", subkategorie: "Dramatische Texte", kbId: "MAP-de-dramenanalyse", landkarte: true, erklaerung: "Hier lernst du, wie man ein Theaterstueck oder eine einzelne Szene genauer untersucht. Du schaust dir an, worauf man bei den Figuren, ihren Gespraechen und dem Aufbau achtet. Diese Werkzeuge brauchst du, um ueber ein Drama schreiben und sprechen zu koennen." },
  { id: "de-tragoedie-und-komoedie", label: "Tragoedie und Komoedie", kategorie: "Epik und Dramatik", subkategorie: "Dramatische Texte", kbId: "MAP-de-tragoedie-und-komoedie", landkarte: true, erklaerung: "In diesem Thema lernst du die zwei klassischen Arten von Theaterstuecken kennen: die ernste Tragoedie und die heitere Komoedie. Du verstehst, worin sie sich unterscheiden und was fuer jede Form typisch ist. So kannst du ein Stueck der passenden Gattung zuordnen." },
  { id: "de-aufbau-eines-dramas", label: "Aufbau eines Dramas", kategorie: "Epik und Dramatik", subkategorie: "Dramatische Texte", kbId: "MAP-de-aufbau-eines-dramas", landkarte: true, erklaerung: "Hier geht es darum, wie ein klassisches Drama von Anfang bis Ende aufgebaut ist. Du lernst, in welche Abschnitte sich die Handlung gliedert und wie sich die Spannung dabei entwickelt. Das hilft dir, den Verlauf eines Theaterstuecks zu durchschauen und zu beschreiben." },
  { id: "de-metapher", label: "Metapher", kategorie: "Stilmittel", subkategorie: "Rhetorische Mittel", kbId: "MAP-de-metapher", landkarte: true, erklaerung: "Hier lernst du die Metapher kennen, ein Stilmittel, bei dem ein Wort in einer ganz anderen, bildlichen Bedeutung benutzt wird. Du verstehst, wie solche sprachlichen Bilder einen Text lebendiger machen und wie du sie in Gedichten und Geschichten aufspuerst. Das hilft dir, Texte genauer zu deuten und selbst anschaulicher zu schreiben." },
  { id: "de-vergleich", label: "Vergleich", kategorie: "Stilmittel", subkategorie: "Rhetorische Mittel", kbId: "MAP-de-vergleich", landkarte: true, erklaerung: "In diesem Thema geht es um den Vergleich, bei dem zwei Dinge mit einem Verbindungswort wie wie oder als nebeneinandergestellt werden. Du lernst, woran du einen Vergleich erkennst und worin er sich von der Metapher unterscheidet. So kannst du Texte besser verstehen und deine eigenen Beschreibungen anschaulicher gestalten." },
  { id: "de-personifikation", label: "Personifikation", kategorie: "Stilmittel", subkategorie: "Rhetorische Mittel", kbId: "MAP-de-personifikation", landkarte: true, erklaerung: "Hier beschaeftigst du dich mit der Personifikation, bei der Dinge oder Tiere so beschrieben werden, als waeren sie Menschen. Du lernst zu erkennen, wann ein Text einem Gegenstand menschliche Eigenschaften gibt und welche Wirkung das hat. Das ist nuetzlich, um die Stimmung in Gedichten und Geschichten zu deuten." },
  { id: "de-hyperbel", label: "Hyperbel", kategorie: "Stilmittel", subkategorie: "Rhetorische Mittel", kbId: "MAP-de-hyperbel", landkarte: true, erklaerung: "In diesem Thema lernst du die Hyperbel kennen, eine starke und absichtliche Uebertreibung. Du verstehst, warum Texte manchmal viel mehr sagen, als wirklich gemeint ist, und welche Wirkung diese Uebertreibung erzeugt. Das hilft dir, solche Stellen richtig einzuordnen und sie nicht woertlich zu nehmen." },
  { id: "de-ironie", label: "Ironie", kategorie: "Stilmittel", subkategorie: "Rhetorische Mittel", kbId: "MAP-de-ironie", landkarte: true, erklaerung: "Hier geht es um die Ironie, bei der jemand das Gegenteil von dem sagt, was eigentlich gemeint ist. Du lernst, wie man erkennt, dass eine Aussage nicht ernst gemeint ist, und worauf man dabei achten muss. Das hilft dir, versteckte Botschaften in Texten und Gespraechen besser zu verstehen." },
  { id: "de-alliteration", label: "Alliteration", kategorie: "Stilmittel", subkategorie: "Klang und Wiederholung", kbId: "MAP-de-alliteration", landkarte: true, erklaerung: "In diesem Thema lernst du die Alliteration kennen, bei der mehrere Woerter hintereinander mit demselben Laut beginnen. Du verstehst, warum solche Klangmuster einen Satz einpraegsam machen und wo sie oft vorkommen, etwa in Spruechen und Werbung. So erkennst du dieses Stilmittel leichter und kannst seine Wirkung beschreiben." },
  { id: "de-anapher", label: "Anapher", kategorie: "Stilmittel", subkategorie: "Klang und Wiederholung", kbId: "MAP-de-anapher", landkarte: true, erklaerung: "Hier beschaeftigst du dich mit der Anapher, bei der am Anfang mehrerer Saetze oder Zeilen dasselbe Wort wiederholt wird. Du lernst, diese Wiederholung zu erkennen und zu verstehen, warum sie eine Aussage betont und eindringlicher macht. Das hilft dir besonders beim Deuten von Gedichten und Reden." },
  { id: "de-parallelismus", label: "Parallelismus", kategorie: "Stilmittel", subkategorie: "Klang und Wiederholung", kbId: "MAP-de-parallelismus", landkarte: true, erklaerung: "In diesem Thema lernst du den Parallelismus kennen, bei dem mehrere Saetze gleich aufgebaut sind. Du verstehst, wie dieser gleiche Satzbau einen Text geordnet und kraftvoll wirken laesst. So kannst du dieses Stilmittel in Gedichten und Reden aufspuren und seine Wirkung erklaeren." },
  { id: "de-rhetorische-frage", label: "Rhetorische Frage", kategorie: "Stilmittel", subkategorie: "Klang und Wiederholung", kbId: "MAP-de-rhetorische-frage", landkarte: true, erklaerung: "Hier geht es um die rhetorische Frage, eine Frage, auf die gar keine Antwort erwartet wird, weil sie schon klar ist. Du lernst zu erkennen, warum solche Fragen gestellt werden und wie sie den Leser oder Zuhoerer zum Nachdenken bringen. Das hilft dir, die Absicht hinter Texten und Reden besser zu verstehen." },
  { id: "de-klimax", label: "Klimax", kategorie: "Stilmittel", subkategorie: "Klang und Wiederholung", kbId: "MAP-de-klimax", landkarte: true, erklaerung: "In diesem Thema lernst du die Klimax kennen, eine Steigerung, bei der Woerter oder Aussagen von schwach zu immer staerker aufeinanderfolgen. Du verstehst, wie diese Steigerung Spannung aufbaut und eine Aussage zuspitzt. So erkennst du das Stilmittel in Texten und kannst beschreiben, was es bewirkt." },
  { id: "de-barock", label: "Barock", kategorie: "Literaturepochen", subkategorie: "Aufklaerung bis Klassik", kbId: "MAP-de-barock", landkarte: true, erklaerung: "Hier geht es um die erste grosse Literaturepoche der Neuzeit, die in eine Zeit voller Kriege und Unsicherheit faellt. Du lernst, welche Lebensgefuehle die Menschen damals bewegt haben und wie sich das in ihren Texten zeigt. Das hilft dir, aeltere Gedichte und ihre besondere Bildsprache besser einzuordnen." },
  { id: "de-aufklaerung", label: "Aufklaerung", kategorie: "Literaturepochen", subkategorie: "Aufklaerung bis Klassik", kbId: "MAP-de-aufklaerung", landkarte: true, erklaerung: "In diesem Thema geht es um eine Zeit, in der der eigene Verstand und das selbststaendige Denken in den Mittelpunkt rueckten. Du erfaehrst, welche Ideen die Menschen damals bewegten und warum Literatur ploetzlich etwas veraendern wollte. Das ist die Grundlage fuer viele Gedanken, die bis heute wichtig sind." },
  { id: "de-sturm-und-drang", label: "Sturm und Drang", kategorie: "Literaturepochen", subkategorie: "Aufklaerung bis Klassik", kbId: "MAP-de-sturm-und-drang", landkarte: true, erklaerung: "Hier lernst du eine Phase kennen, in der junge Autoren gegen feste Regeln aufbegehrten und vor allem Gefuehl und Freiheit betonten. Du verstehst, was diese rebellische Stimmung ausmachte und wogegen sie sich richtete. So bekommst du ein Gespuer fuer eine sehr leidenschaftliche Seite der Literatur." },
  { id: "de-weimarer-klassik", label: "Weimarer Klassik", kategorie: "Literaturepochen", subkategorie: "Aufklaerung bis Klassik", kbId: "MAP-de-weimarer-klassik", landkarte: true, erklaerung: "In diesem Thema geht es um eine Epoche, in der das Schoene, das Wahre und das Gute als Ideal galten und Harmonie eine grosse Rolle spielte. Du erfaehrst, welche beruehmten Dichter diese Zeit gepraegt haben und welche Werte ihnen wichtig waren. Das hilft dir, viele bekannte Werke der deutschen Literatur einzuordnen." },
  { id: "de-romantik", label: "Romantik", kategorie: "Literaturepochen", subkategorie: "Romantik bis Realismus", kbId: "MAP-de-romantik", landkarte: true, erklaerung: "Hier geht es um eine Epoche, in der Gefuehle, Sehnsucht, Natur und das Geheimnisvolle im Mittelpunkt standen. Du lernst, was die Menschen an Traeumen, Maerchen und fernen Welten so faszinierte. Das macht es dir leichter, die stimmungsvollen Texte dieser Zeit zu verstehen." },
  { id: "de-biedermeier-und-vormaerz", label: "Biedermeier und Vormaerz", kategorie: "Literaturepochen", subkategorie: "Romantik bis Realismus", kbId: "MAP-de-biedermeier-und-vormaerz", landkarte: true, erklaerung: "In diesem Thema lernst du eine Zeit kennen, in der zwei sehr unterschiedliche Stroemungen nebeneinander lagen. Du erfaehrst, wie sich der Rueckzug ins gemuetliche Private und der Ruf nach politischer Veraenderung gegenueberstanden. So verstehst du, warum die Literatur damals so gegensaetzlich war." },
  { id: "de-realismus", label: "Realismus", kategorie: "Literaturepochen", subkategorie: "Romantik bis Realismus", kbId: "MAP-de-realismus", landkarte: true, erklaerung: "Hier geht es um eine Epoche, in der die Literatur das echte Leben moeglichst genau und glaubwuerdig zeigen wollte. Du lernst, wie Autoren den Alltag der Menschen beschrieben, ohne ihn zu beschoenigen. Das hilft dir, den Unterschied zu traeumerischen oder uebertriebenen Erzaehlweisen zu erkennen." },
  { id: "de-naturalismus", label: "Naturalismus", kategorie: "Literaturepochen", subkategorie: "Romantik bis Realismus", kbId: "MAP-de-naturalismus", landkarte: true, erklaerung: "In diesem Thema geht es um eine Stroemung, die die Wirklichkeit noch schonungsloser darstellte als der Realismus. Du erfaehrst, warum nun auch Armut, Krankheit und harte Lebensumstaende offen zur Sprache kamen. So verstehst du, wie Literatur die Schattenseiten der Gesellschaft sichtbar machen wollte." },
  { id: "de-expressionismus", label: "Expressionismus", kategorie: "Literaturepochen", subkategorie: "Moderne und Gegenwart", kbId: "MAP-de-expressionismus", landkarte: true, erklaerung: "Hier lernst du eine Epoche kennen, in der starke Gefuehle, Aengste und der Aufbruch in eine neue Zeit besonders kraftvoll ausgedrueckt wurden. Du verstehst, warum die Texte oft aufgewuehlt und ungewoehnlich wirken. Das hilft dir, die eindringliche Sprache dieser Werke einzuordnen." },
  { id: "de-literatur-der-weimarer-republik", label: "Literatur der Weimarer Republik", kategorie: "Literaturepochen", subkategorie: "Moderne und Gegenwart", kbId: "MAP-de-literatur-der-weimarer-republik", landkarte: true, erklaerung: "In diesem Thema geht es um die Literatur einer unruhigen Zeit zwischen zwei Weltkriegen. Du erfaehrst, wie Autoren auf die grossen Veraenderungen, das Stadtleben und die politischen Spannungen reagierten. So bekommst du einen Ueberblick ueber eine sehr vielfaeltige Phase der Literatur." },
  { id: "de-nachkriegsliteratur", label: "Nachkriegsliteratur", kategorie: "Literaturepochen", subkategorie: "Moderne und Gegenwart", kbId: "MAP-de-nachkriegsliteratur", landkarte: true, erklaerung: "Hier geht es um die Literatur nach dem Zweiten Weltkrieg, als viele Menschen vor einem Neuanfang standen. Du lernst, wie Autoren mit Schuld, Zerstoerung und der Suche nach Worten umgingen. Das hilft dir zu verstehen, wie Literatur eine schwere Vergangenheit verarbeiten kann." },
  { id: "de-gegenwartsliteratur", label: "Gegenwartsliteratur", kategorie: "Literaturepochen", subkategorie: "Moderne und Gegenwart", kbId: "MAP-de-gegenwartsliteratur", landkarte: true, erklaerung: "In diesem Thema geht es um die Literatur unserer eigenen Zeit, also um Buecher von heute. Du erfaehrst, welche Themen und Erzaehlweisen moderne Autorinnen und Autoren beschaeftigen. So merkst du, dass Literatur nichts Altes ist, sondern bis in die Gegenwart lebendig bleibt." },
  { id: "de-faust", label: "Faust", kategorie: "Literarische Werke", subkategorie: "Dramen", kbId: "MAP-de-faust", landkarte: true, erklaerung: "Hier geht es um Goethes Faust, eines der bekanntesten Werke der deutschen Literatur. Du lernst kennen, wer Faust ist, was es mit dem Pakt zwischen ihm und dem Teufel Mephisto auf sich hat und welche grossen Fragen das Stueck stellt. Damit bist du gut vorbereitet, wenn der Klassiker im Unterricht oder in einer Pruefung drankommt." },
  { id: "de-woyzeck", label: "Woyzeck", kategorie: "Literarische Werke", subkategorie: "Dramen", kbId: "MAP-de-woyzeck", landkarte: true, erklaerung: "In diesem Thema geht es um Georg Buechners Drama Woyzeck, das von einem einfachen Soldaten und seinem schweren Leben erzaehlt. Du erfaehrst, worum es in dem Stueck geht, welche Figuren wichtig sind und warum es als ungewoehnliches Drama gilt. So findest du dich beim Lesen und Besprechen im Unterricht schnell zurecht." },
  { id: "de-die-physiker", label: "Die Physiker", kategorie: "Literarische Werke", subkategorie: "Dramen", kbId: "MAP-de-die-physiker", landkarte: true, erklaerung: "Hier dreht sich alles um Friedrich Duerrenmatts Komoedie Die Physiker, die in einem Irrenhaus spielt. Du bekommst einen Ueberblick darueber, worum es in dem Stueck geht und welche Frage nach der Verantwortung von Wissenschaft dahintersteckt. Das hilft dir, den Inhalt und die Botschaft des Werks besser zu verstehen." },
  { id: "de-nathan-der-weise", label: "Nathan der Weise", kategorie: "Literarische Werke", subkategorie: "Dramen", kbId: "MAP-de-nathan-der-weise", landkarte: true, erklaerung: "In diesem Thema lernst du Lessings Drama Nathan der Weise kennen, das von verschiedenen Religionen und vom Zusammenleben der Menschen handelt. Du erfaehrst, worum es in dem Stueck geht und welche bekannte Geschichte darin eine wichtige Rolle spielt. So bist du vorbereitet, wenn das Werk im Deutschunterricht behandelt wird." },
  { id: "de-die-verwandlung", label: "Die Verwandlung", kategorie: "Literarische Werke", subkategorie: "Romane und Erzaehlungen", kbId: "MAP-de-die-verwandlung", landkarte: true, erklaerung: "Hier geht es um Franz Kafkas Erzaehlung Die Verwandlung, in der ein Mann eines Morgens als riesiges Insekt aufwacht. Du bekommst einen Ueberblick darueber, worum es in der Geschichte geht und welche Themen wie Familie und Einsamkeit dahinterstecken. Das hilft dir, das ungewoehnliche Werk im Unterricht einordnen zu koennen." },
  { id: "de-der-sandmann", label: "Der Sandmann", kategorie: "Literarische Werke", subkategorie: "Romane und Erzaehlungen", kbId: "MAP-de-der-sandmann", landkarte: true, erklaerung: "In diesem Thema geht es um E.T.A. Hoffmanns unheimliche Erzaehlung Der Sandmann. Du erfaehrst, worum es in der Geschichte geht, welche Figuren wichtig sind und warum das Werk zwischen Wirklichkeit und Einbildung spielt. So findest du dich beim Lesen und Besprechen besser zurecht." },
  { id: "de-homo-faber", label: "Homo faber", kategorie: "Literarische Werke", subkategorie: "Romane und Erzaehlungen", kbId: "MAP-de-homo-faber", landkarte: true, erklaerung: "Hier lernst du Max Frischs Roman Homo faber kennen, der von einem Mann erzaehlt, der alles mit Technik und Logik erklaeren will. Du bekommst einen Ueberblick darueber, worum es in der Geschichte geht und welche Rolle Zufall und Schicksal darin spielen. Das hilft dir, den Roman im Unterricht und in Pruefungen zu verstehen." },
  { id: "de-der-vorleser", label: "Der Vorleser", kategorie: "Literarische Werke", subkategorie: "Romane und Erzaehlungen", kbId: "MAP-de-der-vorleser", landkarte: true, erklaerung: "In diesem Thema geht es um Bernhard Schlinks Roman Der Vorleser, der von einer ungewoehnlichen Beziehung und von Schuld nach dem Zweiten Weltkrieg erzaehlt. Du erfaehrst, worum es in der Geschichte geht und welche grossen Fragen sie aufwirft. So bist du gut vorbereitet, wenn der Roman im Deutschunterricht drankommt." },
  { id: "de-kommunikationsmodelle", label: "Kommunikationsmodelle", kategorie: "Sprache und Kommunikation", subkategorie: "Kommunikation", kbId: "MAP-de-kommunikationsmodelle", landkarte: true, erklaerung: "Kommunikationsmodelle versuchen zu erklaeren, wie eine Nachricht von einem Menschen zum anderen gelangt und warum dabei oft etwas anderes ankommt als gemeint war. Hier verschaffst du dir einen Ueberblick ueber die wichtigsten Modelle und ihre Grundgedanken." },
  { id: "de-sender-empfaenger-modell", label: "Sender-Empfaenger-Modell", kategorie: "Sprache und Kommunikation", subkategorie: "Kommunikation", kbId: "MAP-de-sender-empfaenger-modell", landkarte: true, erklaerung: "Das Sender-Empfaenger-Modell beschreibt Kommunikation als Weg einer Nachricht vom Sender zum Empfaenger. Du lernst hier kennen, welche Rolle Codierung, Kanal und moegliche Stoerungen dabei spielen." },
  { id: "de-vier-ohren-modell", label: "Vier-Ohren-Modell (Schulz von Thun)", kategorie: "Sprache und Kommunikation", subkategorie: "Kommunikation", kbId: "MAP-de-vier-ohren-modell", landkarte: true, erklaerung: "Nach Friedemann Schulz von Thun hat jede Aussage vier Seiten: Sachebene, Selbstkundgabe, Beziehung und Appell. Dieses Kapitel zeigt dir, worum es beim Vier-Ohren-Modell und dem Kommunikationsquadrat geht." },
  { id: "de-watzlawick-axiome", label: "Kommunikationsaxiome (Watzlawick)", kategorie: "Sprache und Kommunikation", subkategorie: "Kommunikation", kbId: "MAP-de-watzlawick-axiome", landkarte: true, erklaerung: "Paul Watzlawick hat fuenf Grundregeln der Kommunikation aufgestellt, etwa dass man nicht nicht kommunizieren kann. Hier bekommst du einen Eindruck davon, was diese Axiome aussagen wollen." },
  { id: "de-gespraechsanalyse", label: "Gespraechs- und Dialoganalyse", kategorie: "Sprache und Kommunikation", subkategorie: "Kommunikation", kbId: "MAP-de-gespraechsanalyse", landkarte: true, erklaerung: "Bei einer Gespraechs- oder Dialoganalyse untersuchst du, wie Personen miteinander reden und was zwischen den Zeilen mitschwingt. Dieses Kapitel ordnet ein, worauf es bei so einer Analyse ankommt." },
  { id: "de-sprachwandel", label: "Sprachwandel", kategorie: "Sprache und Kommunikation", subkategorie: "Sprache im Wandel", kbId: "MAP-de-sprachwandel", landkarte: true, erklaerung: "Sprache veraendert sich staendig, etwa durch neue Woerter, Anglizismen oder den Einfluss der Medien. Hier verschaffst du dir einen Ueberblick darueber, was Sprachwandel bedeutet und warum darueber gestritten wird." },
  { id: "de-sprachvarietaeten", label: "Sprachvarietaeten", kategorie: "Sprache und Kommunikation", subkategorie: "Sprache im Wandel", kbId: "MAP-de-sprachvarietaeten", landkarte: true, erklaerung: "Sprachvarietaeten sind die unterschiedlichen Spielarten einer Sprache, die von der Standardsprache abweichen. Dieses Kapitel zeigt dir, welche Arten es gibt und wodurch sie sich unterscheiden." },
  { id: "de-dialekt-soziolekt", label: "Dialekt und Soziolekt", kategorie: "Sprache und Kommunikation", subkategorie: "Sprache im Wandel", kbId: "MAP-de-dialekt-soziolekt", landkarte: true, erklaerung: "Ein Dialekt ist an eine Region gebunden, ein Soziolekt an eine soziale Gruppe wie etwa die Jugendsprache. Hier lernst du den Unterschied zwischen diesen beiden Sprachformen kennen." },
  { id: "de-spracherwerb", label: "Spracherwerb", kategorie: "Sprache und Kommunikation", subkategorie: "Sprache im Wandel", kbId: "MAP-de-spracherwerb", landkarte: true, erklaerung: "Spracherwerbstheorien beschaeftigen sich mit der Frage, wie Kinder ihre Sprache lernen. Dieses Kapitel gibt dir einen Ueberblick ueber die wichtigsten Erklaerungsansaetze." },
  { id: "de-mehrsprachigkeit", label: "Mehrsprachigkeit", kategorie: "Sprache und Kommunikation", subkategorie: "Sprache im Wandel", kbId: "MAP-de-mehrsprachigkeit", landkarte: true, erklaerung: "Mehrsprachigkeit meint, mehrere Sprachen oder Sprachvarietaeten zu beherrschen, sei es zwischen verschiedenen Sprachen oder innerhalb einer Sprache. Hier ordnest du ein, was aeussere und innere Mehrsprachigkeit bedeuten." },
  { id: "de-erzaehlung", label: "Erzaehlung", kategorie: "Textarten und Schreiben", subkategorie: "Kreatives und erzaehlendes Schreiben", kbId: "MAP-de-erzaehlung", landkarte: true, erklaerung: "Eine Erzaehlung ist ein Text, in dem du ein Geschehen lebendig und spannend wiedergibst. Dieses Kapitel zeigt dir, welche Merkmale eine Erzaehlung ausmachen und welche Formen es gibt." },
  { id: "de-bildergeschichte", label: "Bildergeschichte", kategorie: "Textarten und Schreiben", subkategorie: "Kreatives und erzaehlendes Schreiben", kbId: "MAP-de-bildergeschichte", landkarte: true, erklaerung: "Bei einer Bildergeschichte schreibst du anhand einer vorgegebenen Bilderfolge einen zusammenhaengenden Erzaehltext. Dieses Kapitel ordnet ein, worauf du beim Betrachten der Bilder und beim Schreiben achtest." },
  { id: "de-reizwortgeschichte", label: "Reizwortgeschichte", kategorie: "Textarten und Schreiben", subkategorie: "Kreatives und erzaehlendes Schreiben", kbId: "MAP-de-reizwortgeschichte", landkarte: true, erklaerung: "Bei einer Reizwortgeschichte baust du vorgegebene Reizwoerter in eine selbst erfundene Geschichte ein. Hier verschaffst du dir einen Ueberblick ueber Aufbau und Besonderheiten dieser Textart." },
  { id: "de-materialgestuetztes-schreiben", label: "Materialgestuetztes Schreiben", kategorie: "Textarten und Schreiben", subkategorie: "Argumentierende Texte", kbId: "MAP-de-materialgestuetztes-schreiben", landkarte: true, erklaerung: "Beim materialgestuetzten Schreiben verfasst du einen eigenen informierenden oder argumentierenden Text auf Grundlage mehrerer vorgegebener Materialien. Dieses Kapitel zeigt dir, worum es bei dieser Schreibform geht." },
  { id: "de-filmanalyse", label: "Filmanalyse", kategorie: "Textarten und Schreiben", subkategorie: "Analyse und Interpretation", kbId: "MAP-de-filmanalyse", landkarte: true, erklaerung: "Bei der Filmanalyse untersuchst du, wie ein Film wirkt und mit welchen Mitteln er das macht, etwa durch Kameraeinstellungen, Schnitt und Musik. Hier bekommst du einen Ueberblick, worauf es bei dieser Analyseform ankommt." },
  { id: "de-karikaturanalyse", label: "Karikaturanalyse", kategorie: "Textarten und Schreiben", subkategorie: "Analyse und Interpretation", kbId: "MAP-de-karikaturanalyse", landkarte: true, erklaerung: "Eine Karikatur ueberzeichnet etwas, um Kritik oder eine Meinung auszudruecken. Bei der Karikaturanalyse beschreibst und deutest du so ein Bild. Dieses Kapitel zeigt dir, worum es bei dieser Aufgabenart geht." },
  { id: "de-literarische-eroerterung", label: "Literarische Eroerterung", kategorie: "Textarten und Schreiben", subkategorie: "Argumentierende Texte", kbId: "MAP-de-literarische-eroerterung", landkarte: true, erklaerung: "Bei der literarischen Eroerterung setzt du dich argumentierend mit einem literarischen Werk oder einer These dazu auseinander. Hier erfaehrst du, wie sich diese Form von der textgebundenen und der freien Eroerterung unterscheidet." },
  { id: "de-komposita", label: "Komposita", kategorie: "Grammatik", subkategorie: "Wortbildung", kbId: "MAP-de-komposita", landkarte: true, erklaerung: "Bei Komposita setzt du mehrere Woerter zu einem neuen zusammen, zum Beispiel Haus und Tuer zu Haustuer. Hier lernst du, wie zusammengesetzte Woerter aufgebaut sind und welcher Teil die Bedeutung bestimmt." },
  { id: "de-ableitung", label: "Ableitung (Vorsilbe und Nachsilbe)", kategorie: "Grammatik", subkategorie: "Wortbildung", kbId: "MAP-de-ableitung", landkarte: true, erklaerung: "Bei der Ableitung entstehen neue Woerter, indem du an einen Wortstamm eine Vorsilbe oder Nachsilbe anhaengst, etwa un- oder -heit. Dieses Kapitel zeigt dir, wie aus einem Stamm so neue Woerter werden." },
  { id: "de-wortstamm-wortfamilie", label: "Wortstamm und Wortfamilie", kategorie: "Grammatik", subkategorie: "Wortbildung", kbId: "MAP-de-wortstamm-wortfamilie", landkarte: true, erklaerung: "Der Wortstamm ist der gemeinsame Kern verwandter Woerter, und eine Wortfamilie fasst alle Woerter mit demselben Stamm zusammen. Hier verstehst du, wie du verwandte Woerter erkennst und ordnest." },
  { id: "de-wortfeld", label: "Wortfeld", kategorie: "Grammatik", subkategorie: "Wortbildung", kbId: "MAP-de-wortfeld", landkarte: true, erklaerung: "Ein Wortfeld ist eine Gruppe von Woertern mit aehnlicher Bedeutung, zum Beispiel viele Woerter fuer gehen. Dieses Kapitel zeigt dir, wozu Wortfelder gut sind und wie sie dir beim treffenden Formulieren helfen." },
];
